DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['ad_scan_jobs','campaigns','campaign_sequences','campaign_sequence_steps','imported_leads','imported_lists','intent_leads','prospects','prospect_sequence_enrollments','scraped_ads','sms_delivery_log','sms_opt_outs','scraping_usage','call_event_logs','call_transfer_jobs','prospect_enrichment_jobs','prospect_enrichment_job_items','voice_guardrails','demo_call_attempts','short_links'] LOOP EXECUTE format('CREATE POLICY voice_clients_cannot_access_crm ON public.%I AS RESTRICTIVE FOR ALL TO authenticated USING (public.is_voice_admin()) WITH CHECK (public.is_voice_admin())',t); END LOOP; END $$;
CREATE POLICY authenticated_upload_isolation ON storage.objects AS RESTRICTIVE FOR ALL TO authenticated USING (bucket_id <> 'lead-uploads' OR public.is_voice_admin() OR EXISTS (SELECT 1 FROM public.voice_agents a WHERE split_part(name,'/',1)='voice' AND split_part(name,'/',2)=a.id::text AND public.can_manage_voice(a.organization_id))) WITH CHECK (bucket_id <> 'lead-uploads' OR public.is_voice_admin() OR EXISTS (SELECT 1 FROM public.voice_agents a WHERE split_part(name,'/',1)='voice' AND split_part(name,'/',2)=a.id::text AND public.can_manage_voice(a.organization_id)));